        // One original iterator result; no wrapper iterator or collected copy.
        match self {
            Self::Empty => Iter::empty(),
            Self::Shared(weights) => weights.iter(),
        }
    }
    pub(super) fn get(&self, key: &usize) -> Option<&u64> {
        match self {
            Self::Empty => None,
            Self::Shared(weights) => weights.get(key),
