    pub(super) const ADAPTER_CONTROLS: usize = 2 * size_of::<Self>()
        + 2 * size_of::<Option<Self>>()
        + size_of::<Result<Option<Self>, Diagnostic>>()
        + size_of::<Result<(), Diagnostic>>()
        + size_of::<&ResolvedFunction>()
        + size_of::<&mut ReplayBudget>();
