impl ClosureEntries for super::empty_closure::Closure {
    fn same_entries(&self, expected: &std::collections::BTreeMap<usize, u64>) -> bool {
        match self {
            Self::Empty => expected.is_empty(),
            Self::Shared(value) => value.iter().eq(expected.iter()),
        }
    }
